const item = $input.first().json;
const headers = item.headers || {};
const source = item.body && typeof item.body === 'object' && item.body.event ? item.body : item;
const timestamp = String(headers['x-homestead-timestamp'] || '');
const now = Math.floor(Date.now() / 1000);
const ts = Number(timestamp);
if (!timestamp || !Number.isFinite(ts) || Math.abs(now - ts) > 300) {
  return [{ json: { httpStatus: 401, send: false, response: { ok: false, error: 'unauthorized' } } }];
}
const eventName = String(source.event || '');
if (eventName !== 'control.push.send') {
  return [{ json: { httpStatus: 400, send: false, response: { ok: false, error: 'invalid_event' } } }];
}
const idempotencyKey = String(source.idempotencyKey || headers['x-homestead-idempotency-key'] || '');
if (!idempotencyKey) {
  return [{ json: { httpStatus: 400, send: false, response: { ok: false, error: 'missing_idempotency' } } }];
}
const staticData = $getWorkflowStaticData('global');
staticData.seen = staticData.seen || {};
const cutoff = Date.now() - 7 * 24 * 60 * 60 * 1000;
for (const key of Object.keys(staticData.seen)) {
  if (staticData.seen[key] < cutoff) delete staticData.seen[key];
}
if (staticData.seen[idempotencyKey]) {
  return [{ json: { duplicate: true, httpStatus: 200, send: false, response: { ok: true, duplicate: true, idempotencyKey } } }];
}
staticData.seen[idempotencyKey] = Date.now();
const tokens = Array.isArray(source.fcmTokens) ? source.fcmTokens.map(String).filter(Boolean) : [];
if (!tokens.length) {
  return [{ json: { httpStatus: 200, send: false, response: { ok: true, accepted: 0, reason: 'no_tokens' } } }];
}
const android = source.android || {};
const notification = android.notification || {};
const data = source.data || {};
const dataStrings = {};
for (const [k, v] of Object.entries(data)) dataStrings[String(k)] = String(v == null ? '' : v);
return [{ json: {
  duplicate: false,
  httpStatus: 200,
  send: true,
  idempotencyKey,
  projectId: String($vars.FCM_PROJECT_ID || ''),
  tokens,
  title: String(notification.title || 'Homestead'),
  body: String(notification.body || ''),
  channelId: String(notification.channelId || 'homestead_control_alerts'),
  data: dataStrings,
  response: { ok: true, accepted: tokens.length, idempotencyKey }
} }];

const row = $input.first().json;
const tokens = row.tokens || [];
const projectId = String(row.projectId || '').trim();
if (!projectId) {
  return [{ json: { ...row, sendFcm: false, httpStatus: 500, response: { ok: false, error: 'fcm_project_missing' } } }];
}
const messages = tokens.map((token) => ({
  message: {
    token,
    notification: { title: row.title, body: row.body },
    data: row.data || {},
    android: {
      priority: 'HIGH',
      notification: {
        channelId: row.channelId,
        sound: 'default',
        defaultSound: true
      }
    }
  }
}));
return messages.map((message, index) => ({
  json: {
    projectId,
    message,
    tokenIndex: index,
    idempotencyKey: row.idempotencyKey,
    total: messages.length
  }
}));

const items = $input.all();
let accepted = 0;
const invalidTokenHashes = [];
const failures = [];
for (const item of items) {
  const status = Number(item.json.statusCode || item.json.status || 0);
  const err = item.json.error || item.json.message || null;
  if (item.json.name || (status >= 200 && status < 300) || item.json.message?.name) {
    accepted += 1;
    continue;
  }
  const code = String(item.json.error?.code || item.json.error?.status || err || 'unknown');
  if (/UNREGISTERED|INVALID_ARGUMENT|NOT_FOUND/i.test(JSON.stringify(item.json))) {
    failures.push(code);
  } else {
    failures.push(code);
  }
}
return [{ json: {
  httpStatus: 200,
  response: {
    ok: true,
    fcmAccepted: accepted,
    attempted: items.length,
    failures: failures.slice(0, 20),
    note: 'fcm_accept_is_not_phone_delivery'
  }
} }];
